import sys, os, time, json, re; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from dj import *
tee('d56'); R = {}
pg = PG(9432).start()
m = "from django.db import models\nclass P(models.Model):\n    name = models.CharField(max_length=20)\n    age = models.IntegerField(default=0)\n"
d = proj('d56', files={'lab/models.py': m}, databases=pg.databases(), apps=['django.contrib.contenttypes', 'lab'])
manage(d, 'makemigrations', 'lab')
def err(out):
    L = [l.strip() for l in out.strip().splitlines() if 'Error' in l]; return (L[-1] if L else out.strip().splitlines()[-1])[:150]
def recorded(): return pg.psql("select name from django_migrations where app='lab' order by id") or '(无)'
def reset():
    pg.psql('drop schema public cascade; create schema public'); manage(d, 'migrate', 'contenttypes')
print('== 一:库里已经有同名的表(手工建的),直接 migrate 会怎样')
reset(); pg.psql("create table lab_p (id bigint generated by default as identity primary key, name varchar(20) not null, age integer not null)")
rc, out = manage(d, 'migrate', 'lab'); print('  migrate lab →', err(out)); R['exists'] = err(out); print('  django_migrations 里 lab 的记录:', recorded())
print()
print('== 二:--fake-initial:发现表已存在,只记录、不执行')
rc, out = manage(d, 'migrate', 'lab', '--fake-initial'); print('  ', [l.strip() for l in out.strip().splitlines() if '0001' in l]); R['fake_initial'] = [l.strip() for l in out.strip().splitlines() if '0001' in l]; print('  记录:', recorded())
rc, o = pyscript(d, "from lab.models import P\nP.objects.create(name='x'); print('可以正常读写:', P.objects.count())"); print('  ', o.strip()); R['rw'] = o.strip()
print()
print('== 三:表存在但少一列(手工表没有 age):--fake-initial 会不会发现')
reset(); pg.psql("create table lab_p (id bigint generated by default as identity primary key, name varchar(20) not null)")
rc, out = manage(d, 'migrate', 'lab', '--fake-initial'); print('  ', [l.strip() for l in out.strip().splitlines() if '0001' in l]); R['missing_col'] = [l.strip() for l in out.strip().splitlines() if '0001' in l]
rc, o = pyscript(d, "from lab.models import P\ntry: P.objects.create(name='x')\nexcept Exception as e: print(type(e).__name__ + ':', str(e).splitlines()[0][:90])"); print('  之后读写:', o.strip()); R['missing_use'] = o.strip()
print()
print('== 四:--fake(不限于初始迁移):只写记录,完全不碰数据库')
reset(); (d / 'lab' / 'models.py').write_text(m + "    email = models.CharField(max_length=40, default='')\n"); manage(d, 'makemigrations', 'lab', '--noinput', '-n', 'email'); manage(d, 'migrate', 'lab', '0001')
rc, out = manage(d, 'migrate', 'lab', '--fake'); print('  migrate lab --fake:', [l.strip() for l in out.strip().splitlines() if 'FAKED' in l]); print('  记录:', recorded().replace('\n', ' , '))
cols = pg.psql("select column_name from information_schema.columns where table_name='lab_p' order by ordinal_position").replace('\n', ','); print('  数据库里 lab_p 的列:', cols, ' ← 没有 email');
rc, o = pyscript(d, "from lab.models import P\ntry: P.objects.create(name='x')\nexcept Exception as e: print(type(e).__name__ + ':', str(e).splitlines()[0][:90])"); print('  之后写入:', o.strip()); R['fake_email'] = dict(cols=cols, use=o.strip())
print()
print('== 五:--fake 回退:migrate lab zero --fake 只删记录,表还在')
rc, out = manage(d, 'migrate', 'lab', 'zero', '--fake'); print('  ', [l.strip() for l in out.strip().splitlines() if 'FAKED' in l]); print('  记录:', recorded(), ' 表 lab_p 还在吗:', pg.psql("select count(*) from information_schema.tables where table_name='lab_p'")); R['fake_zero'] = dict(rec=recorded(), table=pg.psql("select count(*) from information_schema.tables where table_name='lab_p'"))
pg.stop(); save('d56', R)
